            int mask1 = (a_vec[1] > 0.0f) ? 1 : 0;
            int mask2 = (a_vec[2] > 0.0f) ? 1 : 0;
            int mask3 = (a_vec[3] > 0.0f) ? 1 : 0;

            // Process each element sequentially to maintain j ordering
            if (mask0) {
                j++;
